import json
from http.server import BaseHTTPRequestHandler, HTTPServer
from urllib.parse import urlparse, parse_qs


class AverageSpeedHandler(BaseHTTPRequestHandler):
    def do_GET(self):
        parsed = urlparse(self.path)
        if parsed.path != "/api/average-speed":
            self.send_error(404)
            return

        query = parse_qs(parsed.query)

        if "distance" not in query or "hours" not in query:
            self._send_error(400, "distance and hours are required")
            return

        raw_distance = query["distance"][0]
        raw_hours = query["hours"][0]

        try:
            distance = float(raw_distance)
            hours = float(raw_hours)
        except (TypeError, ValueError):
            self._send_error(400, "distance and hours must be numbers")
            return

        if hours <= 0:
            self._send_error(400, "hours must be greater than 0")
            return

        average = distance / hours
        result = {"average_speed": round(average, 2)}

        body = json.dumps(result).encode("utf-8")
        self.send_response(200)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def _send_error(self, code, message):
        body = json.dumps({"error": message}).encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def log_message(self, format, *args):
        pass


def main():
    server = HTTPServer(("0.0.0.0", 8000), AverageSpeedHandler)
    print("Server running on http://0.0.0.0:8000")
    server.serve_forever()


